# AUTO-GENERATED by Claude Code
# Purpose: e2e tests of moving up and down the chat (services/ui, assets/panes.js): the round ↑
#          and ↓ buttons over the chat, and Alt+Up / Alt+Down (a row) and Alt+Shift+Up /
#          Alt+Shift+Down (a message you sent). The rows are put in the page by the test: a
#          message of yours only comes from asking the AI, which an e2e test never does.
# Usage: ds test e2e -k e2e_chat_jump   (needs the app running; see conftest.py)
# ---------------------------------------------------------------------------
from __future__ import annotations

from typing import TYPE_CHECKING

import pytest

if TYPE_CHECKING:
    from tests.services.ui.e2e.conftest import App

TURNS = 5
# each turn: your message, two tool calls, a long answer, what it cost (ids: u3, s3a, s3b, a3)
FILL = """(turns) => {
  const items = document.querySelector('.chat-items');
  const row = (id, classes, height) => {
    const node = document.createElement('div');
    node.id = id; node.className = classes; node.textContent = id; node.style.minHeight = height + 'px';
    items.append(node);
  };
  for (let n = 1; n <= turns; n++) {
    row(`u${n}`, 'bubble is-user', 30);
    row(`s${n}a`, 'tool-step mono', 20);
    row(`s${n}b`, 'tool-step mono', 20);
    row(`a${n}`, 'bubble md', 1600);
    row(`c${n}`, 'turn-usage mono', 16);
  }
}"""
# is this row the one at the top of the chat (under the gap kept above it)?
AT_TOP = """(id) => {
  const chat = document.querySelector('.chat-scroll');
  const gap = document.getElementById(id).getBoundingClientRect().top - chat.getBoundingClientRect().top;
  return gap > 4 && gap < 30;
}"""
AT_START = """() => {
  const chat = document.querySelector('.chat-scroll');
  return chat.scrollHeight - chat.clientHeight - Math.abs(chat.scrollTop) < 2;
}"""
SHOWN = "(selector) => getComputedStyle(document.querySelector(selector)).display !== 'none'"
HIDDEN = "(selector) => getComputedStyle(document.querySelector(selector)).display === 'none'"


def fill(app: App) -> None:
    app.show("chat")
    app.chat_box.click()  # the chat is the pane you are in, and the page has seen a click
    app.page.evaluate(FILL, TURNS)
    app.page.wait_for_function(SHOWN, arg=".chat-up")


def test_an_empty_chat_has_no_buttons(app: App) -> None:
    app.show("chat")
    app.chat_box.click()
    assert app.page.evaluate(HIDDEN, ".chat-up")
    assert app.page.evaluate(HIDDEN, ".chat-bottom")


@pytest.mark.smoke
def test_the_up_button_walks_up_the_messages_you_sent(app: App) -> None:
    fill(app)
    assert app.page.evaluate(HIDDEN, ".chat-bottom")  # at the newest message: only ↑
    app.page.click(".chat-up")
    app.page.wait_for_function(AT_TOP, arg=f"u{TURNS}")
    app.page.wait_for_function(SHOWN, arg=".chat-bottom")
    app.page.click(".chat-up")
    app.page.wait_for_function(AT_TOP, arg=f"u{TURNS - 1}")
    # past the first one: the top of the chat, where ↑ goes away
    for _ in range(TURNS):
        app.page.click(".chat-up")
    app.page.wait_for_function(HIDDEN, arg=".chat-up")
    # ↓ as before: back to the newest message
    app.page.click(".chat-bottom")
    app.page.wait_for_function("() => Math.abs(document.querySelector('.chat-scroll').scrollTop) < 2")
    app.page.wait_for_function(HIDDEN, arg=".chat-bottom")


def test_shift_click_goes_to_the_top_of_the_chat(app: App) -> None:
    fill(app)
    app.page.click(".chat-up", modifiers=["Shift"])
    app.page.wait_for_function(HIDDEN, arg=".chat-up")
    app.page.wait_for_function(AT_START)


def test_alt_arrows_step_a_row_and_with_shift_a_message(app: App) -> None:
    fill(app)
    last = TURNS
    app.chat_box.press("Alt+Shift+ArrowUp")
    app.page.wait_for_function(AT_TOP, arg=f"u{last}")
    app.chat_box.press("Alt+ArrowDown")
    app.page.wait_for_function(AT_TOP, arg=f"s{last}a")
    # up a row twice: your message, then the answer before it (what it cost is no stop)
    app.chat_box.press("Alt+ArrowUp")
    app.page.wait_for_function(AT_TOP, arg=f"u{last}")
    app.chat_box.press("Alt+ArrowUp")
    app.page.wait_for_function(AT_TOP, arg=f"a{last - 1}")
    app.chat_box.press("Alt+Shift+ArrowUp")
    app.page.wait_for_function(AT_TOP, arg=f"u{last - 1}")
    app.chat_box.press("Alt+Shift+ArrowDown")
    app.page.wait_for_function(AT_TOP, arg=f"u{last}")
    # two presses in a row, before the first scroll ends, are two steps
    app.chat_box.press("Alt+Shift+ArrowUp")
    app.chat_box.press("Alt+Shift+ArrowUp")
    app.page.wait_for_function(AT_TOP, arg=f"u{last - 2}")
    assert app.chat_box.input_value() == ""  # the keys typed nothing and brought no history back
